*{box-sizing:border-box} :root{--ink:#20352f;--muted:#75817b;--green:#316650;--green-dark:#234c3d;--gold:#c29345;--cream:#f6f3eb;--paper:#fffefa;--line:#e9e6dc;--soft-green:#eaf1e9} body{margin:0;background:var(--cream);color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh;background-image:radial-gradient(#d9d4c6 0.65px,transparent .65px);background-size:18px 18px}.app-shell{max-width:1120px;padding:0 40px;margin:auto}.topbar{height:84px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e8e4d9}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink);font-size:21px;font-weight:700;letter-spacing:-1.1px}.brand-light{font-weight:400;color:#81877e;margin:0 1px}.brand-mark{width:34px;height:34px;border-radius:11px;background:var(--green);display:grid;place-items:center;box-shadow:0 4px 10px #315d4628}.brand-mark svg{width:21px;height:21px;fill:none;stroke:#fffaf0;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}.brand-mark .leaf{stroke:#d9bd7a;stroke-width:1.4}.top-right{display:flex;align-items:center;gap:18px}.saved-label{font-size:12px;color:#6d7a72;font-weight:600;letter-spacing:.02em;display:flex;gap:8px;align-items:center}.live-dot{height:7px;width:7px;border-radius:50%;background:#76a879;box-shadow:0 0 0 3px #76a87922}.sound-button{width:34px;height:34px;border-radius:50%;border:1px solid #e3dfd3;color:#768178;background:#fffefa;font-size:17px;cursor:pointer}.screen{animation:appear .35s ease both}.hidden{display:none!important}.home-screen{padding-top:26px}.hero-card{min-height:304px;border-radius:18px;position:relative;overflow:hidden;background:#e9efe5;display:flex;box-shadow:0 5px 20px #3346310b}.hero-copy{z-index:2;padding:39px 48px;width:57%}.eyebrow,.section-kicker{font-size:10px;letter-spacing:.16em;font-weight:700;color:#738375}.eyebrow{display:flex;align-items:center;gap:9px}.eyebrow-line{width:18px;height:1px;background:#a2ad9e}.hero-copy h1{font-family:'Playfair Display',serif;font-size:43px;line-height:1.12;letter-spacing:-1.1px;margin:17px 0 11px;color:#233b32}.hero-copy h1 em{font-weight:600;color:#527c5d}.hero-subtitle{max-width:345px;color:#69776e;font-size:13px;line-height:1.75;margin:0}.hero-meta{display:flex;align-items:center;gap:10px;color:#718075;font-size:10px;margin-top:22px;font-weight:600}.avatar-stack{display:flex}.avatar-stack span{width:23px;height:23px;display:grid;place-items:center;margin-right:-5px;border:2px solid #e9efe5;border-radius:50%;background:#d6e0d1;color:#527655;font-size:10px}.avatar-stack span:nth-child(2){background:#f0dfc0;color:#9a7540}.avatar-stack span:nth-child(3){background:#ead9d0;color:#a26759}.hero-art{position:absolute;inset:0 0 0 auto;width:48%;overflow:hidden;background:linear-gradient(115deg,#e9efe500 0%,#dce8da 58%,#d2e0d0 100%);display:flex;justify-content:center;align-items:center}.sun-halo{position:absolute;width:222px;height:222px;border-radius:50%;background:#f6f3e7;opacity:.72;right:84px;top:21px}.book{position:absolute;width:206px;height:142px;right:95px;top:75px;transform:rotate(-8deg);filter:drop-shadow(0 13px 10px #50614731)}.book:before{content:'';position:absolute;bottom:-8px;left:8px;right:7px;height:20px;background:#94784d;border-radius:4px 4px 12px 12px;transform:skewX(-10deg)}.book-page{position:absolute;top:0;width:99px;height:137px;background:#fffaf0;border:1px solid #e5dbc6;padding:20px 14px;box-shadow:inset 0 -7px #f4eddd}.left-page{left:4px;border-radius:8px 2px 3px 8px;transform:skewY(5deg)}.right-page{right:4px;border-radius:2px 8px 8px 3px;transform:skewY(-5deg);background:#fffdf6}.book-spine{position:absolute;z-index:2;left:101px;top:3px;height:132px;width:5px;background:#c4aa78;border-radius:50%;transform:rotate(-2deg)}.book-cross{font-family:serif;display:block;text-align:center;color:#709074;font-size:23px;margin:-4px 0 9px}.book-lines{display:block;width:68px;height:2px;background:#d9d4c6;margin:8px auto}.book-lines.short{width:42px}.book-lines.medium{width:55px}.page-title{font-family:'Playfair Display',serif;font-size:12px;line-height:1.35;display:block;text-align:center;color:#56735b;margin:3px 0 12px;letter-spacing:.1em}.art-caption{position:absolute;right:37px;bottom:17px;color:#748576;text-align:right;font-family:'Playfair Display',serif;font-size:11px;font-style:italic;line-height:1.4}.art-caption small{display:block;font:9px 'DM Sans',sans-serif;margin-top:2px}.spark,.tiny-star{position:absolute;color:#ba9a5d}.spark{font-size:20px}.spark-one{top:48px;right:77px}.spark-two{top:84px;right:327px;font-size:14px}.tiny-star{font-size:11px}.star-a{right:58px;top:143px}.star-b{right:326px;bottom:67px}.start-panel{background:var(--paper);border:1px solid #edeae1;border-radius:16px;margin-top:20px;padding:23px 27px 19px;box-shadow:0 7px 22px #283b2d08}.section-heading{display:flex;align-items:center;justify-content:space-between}.section-kicker{font-size:9px;letter-spacing:.15em}.section-heading h2{font-family:'Playfair Display',serif;margin:4px 0 0;font-size:21px;letter-spacing:-.3px}.round-pill{border-radius:20px;padding:8px 12px;background:#f4f3ec;color:#7a8179;font-size:10px;font-weight:600}.round-pill span{color:#aa8850;margin-right:4px}.category-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:17px}.category-card{min-height:62px;background:#fffefa;border:1px solid #eae8df;border-radius:10px;padding:10px;display:flex;align-items:center;text-align:left;gap:10px;cursor:pointer;transition:.18s ease;position:relative;color:var(--ink)}.category-card:hover{border-color:#b9c9b8;transform:translateY(-1px)}.category-card.active{background:#f7faf5;border-color:#789779;box-shadow:inset 0 0 0 1px #78977933}.category-icon{width:34px;height:34px;flex:none;border-radius:9px;display:grid;place-items:center;font-size:17px}.all-icon{background:#edf1df;color:#789052}.old-icon{background:#f5ead7;color:#b38a4b}.new-icon{background:#e8eef0;color:#668795}.category-text{display:flex;flex-direction:column;gap:3px}.category-text strong{font-size:11px;font-weight:700}.category-text small{font-size:9px;color:#8b9189}.category-check{margin-left:auto;width:17px;height:17px;border-radius:50%;background:#34684f;color:white;font-size:10px;display:none;place-items:center}.active .category-check{display:grid}.start-row{display:flex;align-items:center;justify-content:space-between;margin-top:17px;padding-top:14px;border-top:1px solid #efede6}.best-score{display:flex;align-items:center;gap:9px}.trophy{width:31px;height:31px;display:grid;place-items:center;border-radius:9px;background:#f7f0df;color:#b68d4b;font-size:19px}.best-score span:last-child{display:flex;flex-direction:column;gap:2px}.best-score small{font-size:8px;letter-spacing:.1em;color:#899087;font-weight:700}.best-score strong{font-size:12px;color:#48584d}.primary-button{background:#32674f;color:#fffdf7;border:none;border-radius:8px;padding:12px 18px;font:700 12px 'DM Sans',sans-serif;display:flex;align-items:center;gap:22px;cursor:pointer;box-shadow:0 5px 12px #32674f27;transition:.18s}.primary-button:hover{background:#254f3d;transform:translateY(-1px);box-shadow:0 7px 14px #32674f38}.primary-button span{font-size:17px;line-height:10px}.home-footer{display:flex;align-items:center;justify-content:space-between;margin:19px 2px 0;color:#9a9d92;font-size:9px}.home-footer>span:last-child{font-size:8px;letter-spacing:.1em;font-weight:700}.footer-heart{color:#b89159;margin-left:4px}.quiz-screen{padding:27px 0 30px;max-width:760px;margin:auto}.quiz-topline{display:flex;align-items:center;justify-content:space-between;margin:0 0 14px}.back-button{border:0;background:transparent;color:#738078;font:600 11px 'DM Sans';cursor:pointer;padding:7px 0}.back-button span{font-size:17px;vertical-align:-1px;margin-right:5px}.quiz-category{font-size:9px;letter-spacing:.14em;font-weight:700;color:#7d8b7f}.score-chip{background:#fffefa;border:1px solid #ece9df;border-radius:18px;padding:7px 11px;font-size:10px;color:#758078}.score-chip span{color:#be995c}.score-chip b{color:#405448}.quiz-card{background:#fffefa;border:1px solid #eae7dd;border-radius:15px;overflow:hidden;padding:0 35px 25px;box-shadow:0 8px 24px #273c2b0b}.quiz-progress-line{height:3px;background:#f0eee7;margin:0 -35px}.progress-fill{height:100%;width:20%;background:#699072;transition:width .4s ease}.question-meta{display:flex;justify-content:space-between;margin-top:24px;color:#92988e;font-size:9px;letter-spacing:.12em;font-weight:700}.streak{letter-spacing:0;color:#a6874f}.question-body{text-align:center;padding:16px 0 17px}.question-illustration{margin:0 auto 10px;width:44px;height:44px;border-radius:14px;background:#edf2e8;display:grid;place-items:center;color:#638464;font-size:21px}.question-body h2{font-family:'Playfair Display',serif;font-size:24px;line-height:1.35;margin:0 auto;color:#283d33;max-width:570px}.question-body p{margin:8px 0 0;color:#969a91;font-size:11px}.answers{display:grid;grid-template-columns:1fr 1fr;gap:10px}.answer{min-height:53px;padding:10px 12px;border:1px solid #e9e7de;border-radius:9px;background:#fffefa;color:#4d5c51;text-align:left;font:600 11px 'DM Sans';display:flex;align-items:center;gap:10px;cursor:pointer;transition:.16s}.answer:hover:not(:disabled){border-color:#93ad91;background:#f8faf6}.answer .letter{width:25px;height:25px;display:grid;place-items:center;border-radius:7px;background:#f4f3ed;color:#8b9289;font-size:10px;flex:none}.answer.correct{border-color:#7ca47d;background:#f1f8ef;color:#37603f}.answer.correct .letter{background:#dcebd8;color:#4b8151}.answer.wrong{border-color:#d99481;background:#fff4f0;color:#9c5547}.answer.wrong .letter{background:#f7dfd8;color:#a55d4e}.answer:disabled{cursor:default}.feedback{height:29px;padding-top:10px;text-align:center;font-size:10px;font-weight:600;color:#6a886c}.feedback.incorrect{color:#ad685b}.next-button{margin:0 auto;display:flex;align-items:center;justify-content:center;gap:18px;border:0;border-radius:8px;background:#32674f;color:white;padding:11px 17px;font:700 11px 'DM Sans';cursor:pointer;transition:.18s}.next-button:hover:not(:disabled){background:#254f3d}.next-button:disabled{opacity:.42;cursor:not-allowed}.next-button span{font-size:16px}.quiz-verse{display:flex;justify-content:center;align-items:center;gap:8px;margin:21px auto 0;color:#899188;font-family:'Playfair Display',serif;font-size:12px;font-style:italic}.quiz-verse span{font-size:20px;color:#b69a68}.result-screen{max-width:720px;margin:25px auto}.result-card{background:#fffefa;border:1px solid #ebe8de;border-radius:17px;text-align:center;padding:28px 40px 24px;position:relative;overflow:hidden;box-shadow:0 8px 25px #283b2d0b}.result-confetti{position:absolute;top:24px;left:0;right:0;color:#c6a463;font-size:15px;letter-spacing:80px;opacity:.7}.result-medal{width:63px;height:63px;border-radius:50%;margin:2px auto 13px;background:#edf2e9;border:1px solid #dde7d8;display:grid;place-items:center;color:#638266;font-size:26px;box-shadow:0 0 0 7px #f8faf5}.result-card h1{font:700 34px 'Playfair Display';margin:7px 0 4px;color:#273d32}.result-card>p{margin:0;color:#838c83;font-size:12px}.result-score{display:flex;flex-direction:column;align-items:center;margin:15px 0 13px}.result-score strong{font:700 52px 'Playfair Display';line-height:1;color:#416d4d}.result-score>span{font-size:11px;color:#7d887f;margin-top:2px}.result-score small{font-size:10px;color:#a1a39a;margin-top:5px}.result-stats{display:flex;justify-content:center;align-items:center;gap:28px;background:#f7f7f1;border-radius:10px;max-width:440px;margin:0 auto 18px;padding:12px}.result-stats>div{display:grid;grid-template-columns:17px auto;grid-template-rows:auto auto;column-gap:5px;text-align:left}.result-stats>div span{grid-row:1/3;align-self:center;color:#ba9656}.result-stats strong{font-size:13px;color:#526455}.result-stats small{font-size:7px;letter-spacing:.08em;color:#9a9e94;margin-top:2px}.result-stats i{height:24px;width:1px;background:#e4e3db}.play-again{margin:auto;min-width:190px;justify-content:center}.text-button{margin-top:11px;background:none;border:0;color:#828a80;font:600 10px 'DM Sans';cursor:pointer}.text-button:hover{color:#32674f}.result-screen .home-footer{justify-content:center;margin-top:14px}.toast{position:fixed;bottom:22px;left:50%;transform:translate(-50%,15px);background:#263f33;color:#fff;padding:10px 16px;border-radius:8px;font-size:11px;opacity:0;pointer-events:none;transition:.25s;box-shadow:0 5px 16px #20352f33}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes appear{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:700px){.app-shell{padding:0 19px}.topbar{height:68px}.saved-label{font-size:0}.saved-label .live-dot{width:8px;height:8px}.home-screen{padding-top:17px}.hero-card{min-height:440px;display:block}.hero-copy{padding:29px 25px;width:100%}.hero-copy h1{font-size:38px;margin-top:13px}.hero-subtitle{font-size:12px;max-width:310px}.hero-meta{margin-top:14px}.hero-art{top:auto;bottom:0;width:100%;height:205px;background:linear-gradient(0deg,#dce8da 20%,#e9efe500 100%)}.sun-halo{width:157px;height:157px;right:calc(50% - 78px);top:6px}.book{transform:rotate(-8deg) scale(.8);right:calc(50% - 101px);top:20px}.art-caption{right:16px;bottom:6px;font-size:9px}.spark-one{top:17px;right:calc(50% - 115px)}.spark-two{top:52px;right:calc(50% + 111px)}.star-a{right:calc(50% - 134px);top:115px}.star-b{right:calc(50% + 132px);bottom:33px}.start-panel{margin-top:14px;padding:19px 16px 15px}.section-heading h2{font-size:19px}.round-pill{font-size:9px;padding:7px 9px}.category-grid{grid-template-columns:1fr;gap:7px;margin-top:14px}.category-card{min-height:54px;padding:8px}.category-icon{height:32px;width:32px}.category-text strong{font-size:11px}.category-text small{font-size:9px}.start-row{margin-top:13px;padding-top:12px}.best-score small{font-size:7px}.primary-button{padding:11px 13px;gap:12px;font-size:11px}.home-footer{font-size:8px;margin-top:14px}.quiz-screen{padding-top:18px}.quiz-card{padding:0 17px 21px}.quiz-progress-line{margin:0 -17px}.question-meta{margin-top:19px;font-size:8px}.question-body{padding:16px 0}.question-body h2{font-size:21px}.answers{grid-template-columns:1fr;gap:7px}.answer{min-height:48px}.feedback{height:31px}.quiz-verse{font-size:10px;margin-top:16px}.result-screen{margin-top:18px}.result-card{padding:26px 18px 21px}.result-card h1{font-size:30px}.result-confetti{letter-spacing:45px}.result-stats{gap:14px;padding:11px 7px}.result-stats small{font-size:6px}.result-stats>div{grid-template-columns:14px auto;column-gap:3px}.result-screen .home-footer{font-size:8px;text-align:center}}
@media(max-width:360px){.app-shell{padding:0 13px}.hero-copy{padding-left:20px}.section-heading{align-items:flex-start}.round-pill{margin-top:6px}.best-score{gap:6px}.start-row .primary-button{gap:8px;padding:10px}.result-stats{gap:8px}}

const questions = [
  {category:'antiguo',icon:'⌂',question:'¿Quién construyó un arca para salvar a su familia y a los animales?',options:['Abraham','Noé','Moisés','David'],answer:'Noé',reference:'Génesis 6:13–22',explanation:'Dios pidió a Noé que construyera el arca antes del diluvio.'},
  {category:'antiguo',icon:'☼',question:'¿Qué mar se abrió para que el pueblo de Israel pudiera escapar de Egipto?',options:['Mar Muerto','Mar de Galilea','Mar Rojo','Mar Mediterráneo'],answer:'Mar Rojo',reference:'Éxodo 14:21–22',explanation:'Moisés extendió su mano y el Señor abrió un camino en el mar.'},
  {category:'antiguo',icon:'♩',question:'¿Qué joven pastor derrotó al gigante Goliat?',options:['Salomón','Samuel','David','Josué'],answer:'David',reference:'1 Samuel 17:45–50',explanation:'David venció a Goliat con una honda y una piedra, confiando en Dios.'},
  {category:'antiguo',icon:'✦',question:'¿Cuántos días y noches llovió durante el diluvio?',options:['7','12','40','100'],answer:'40',reference:'Génesis 7:12',explanation:'La lluvia cayó sobre la tierra durante cuarenta días y cuarenta noches.'},
  {category:'antiguo',icon:'☁',question:'¿En qué monte recibió Moisés los Diez Mandamientos?',options:['Monte Carmelo','Monte Sinaí','Monte de los Olivos','Monte Ararat'],answer:'Monte Sinaí',reference:'Éxodo 19:20; 20:1–17',explanation:'Dios entregó sus mandamientos a Moisés en el monte Sinaí.'},
  {category:'antiguo',icon:'♜',question:'¿Qué profeta fue tragado por un gran pez?',options:['Elías','Isaías','Jonás','Jeremías'],answer:'Jonás',reference:'Jonás 1:17',explanation:'Jonás estuvo dentro del gran pez tres días y tres noches.'},
  {category:'antiguo',icon:'♛',question:'¿Qué pidió Salomón a Dios cuando llegó a ser rey?',options:['Riquezas','Una larga vida','Sabiduría','Un gran ejército'],answer:'Sabiduría',reference:'1 Reyes 3:9–12',explanation:'Salomón pidió sabiduría para gobernar bien al pueblo.'},
  {category:'antiguo',icon:'♧',question:'¿Quién interpretó los sueños del faraón en Egipto?',options:['José','Daniel','Aarón','Jacob'],answer:'José',reference:'Génesis 41:14–16, 25–32',explanation:'José explicó que los sueños anunciaban siete años de abundancia y siete de hambre.'},
  {category:'nuevo',icon:'✧',question:'¿En qué ciudad nació Jesús?',options:['Nazaret','Jerusalén','Belén','Capernaúm'],answer:'Belén',reference:'Lucas 2:4–7',explanation:'Jesús nació en Belén, la ciudad de David.'},
  {category:'nuevo',icon:'♧',question:'¿Cuál fue el primer milagro de Jesús, según el Evangelio de Juan?',options:['Sanó a un ciego','Convirtió agua en vino','Calmó una tormenta','Multiplicó los panes'],answer:'Convirtió agua en vino',reference:'Juan 2:1–11',explanation:'En las bodas de Caná, Jesús convirtió el agua en vino.'},
  {category:'nuevo',icon:'♧',question:'¿Cuántos discípulos escogió Jesús?',options:['7','10','12','40'],answer:'12',reference:'Lucas 6:12–16',explanation:'Jesús llamó a doce discípulos para que estuvieran con él y fueran enviados.'},
  {category:'nuevo',icon:'♡',question:'¿Quién negó conocer a Jesús tres veces?',options:['Juan','Pedro','Tomás','Andrés'],answer:'Pedro',reference:'Lucas 22:54–62',explanation:'Pedro recordó las palabras de Jesús y lloró amargamente.'},
  {category:'nuevo',icon:'♧',question:'¿Qué hizo el buen samaritano por el hombre herido?',options:['Lo llevó a una posada y lo cuidó','Lo dejó con los sacerdotes','Le dio una moneda y siguió','Llamó a los soldados'],answer:'Lo llevó a una posada y lo cuidó',reference:'Lucas 10:30–35',explanation:'El samaritano tuvo compasión, curó sus heridas y pagó para que lo cuidaran.'},
  {category:'nuevo',icon:'♧',question:'¿Qué discípulo caminó sobre el agua hacia Jesús?',options:['Santiago','Felipe','Pedro','Mateo'],answer:'Pedro',reference:'Mateo 14:28–31',explanation:'Pedro salió de la barca y caminó sobre el agua hacia Jesús.'},
  {category:'nuevo',icon:'☼',question:'¿Qué alimento compartió Jesús para alimentar a cinco mil personas?',options:['Siete panes y dos peces','Cinco panes y dos peces','Cinco panes y cinco peces','Doce panes y un pez'],answer:'Cinco panes y dos peces',reference:'Mateo 14:17–21',explanation:'Jesús bendijo cinco panes y dos peces, y todos comieron hasta quedar satisfechos.'},
  {category:'nuevo',icon:'✉',question:'¿Quién escribió muchas cartas que aparecen en el Nuevo Testamento?',options:['Pablo','Herodes','Pilato','Zaqueo'],answer:'Pablo',reference:'Por ejemplo: Romanos 1:1',explanation:'Pablo escribió cartas a distintas comunidades cristianas para animarlas y enseñarles.'}
];

const screens = {home:document.querySelector('#homeScreen'),quiz:document.querySelector('#quizScreen'),result:document.querySelector('#resultScreen')};
const categoryNames = {all:'UN POCO DE TODO',antiguo:'ANTIGUO TESTAMENTO',nuevo:'NUEVO TESTAMENTO'};
let selectedCategory = 'all';
let round = [];
let current = 0;
let score = 0;
let correctAnswers = 0;
let streak = 0;
let bestStreak = 0;
let locked = false;
let soundOn = false;
let audioContext;

const bestScoreKey = 'retoDeFeBestScore';
const bestScoreEl = document.querySelector('#bestScore');
function getBestScore(){ return Number(localStorage.getItem(bestScoreKey) || 0); }
function refreshBestScore(){ const best=getBestScore(); bestScoreEl.textContent=best ? `${best} pts` : 'Aún sin récord'; }
function showScreen(name){ Object.values(screens).forEach(s=>s.classList.add('hidden')); screens[name].classList.remove('hidden'); window.scrollTo({top:0,behavior:'smooth'}); }
function showHome(){ showScreen('home'); refreshBestScore(); }
function shuffle(list){ const result=[...list]; for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result; }
function startGame(){
  const pool=questions.filter(q=>selectedCategory==='all'||q.category===selectedCategory);
  round=shuffle(pool).slice(0,5); current=0; score=0; correctAnswers=0; streak=0; bestStreak=0; locked=false;
  document.querySelector('#liveScore').textContent='0';
  document.querySelector('#quizCategory').textContent=categoryNames[selectedCategory];
  showScreen('quiz'); renderQuestion();
}
function renderQuestion(){
  locked=false;
  const q=round[current];
  document.querySelector('#questionCount').textContent=`PREGUNTA ${current+1} DE ${round.length}`;
  document.querySelector('#progressFill').style.width=`${(current/round.length)*100}%`;
  document.querySelector('#questionIcon').textContent=q.icon;
  document.querySelector('#questionText').textContent=q.question;
  document.querySelector('#questionHint').textContent='Elige la respuesta correcta';
  document.querySelector('#streakLabel').textContent=streak>1?`⚡ Racha de ${streak}`:'✧ ¡A por ello!';
  const answers=document.querySelector('#answers'); answers.innerHTML='';
  const letters=['A','B','C','D'];
  shuffle(q.options).forEach((option,index)=>{
    const button=document.createElement('button'); button.className='answer'; button.type='button';
    const letter=document.createElement('span');letter.className='letter';letter.textContent=letters[index];
    const text=document.createElement('span');text.textContent=option;
    button.append(letter,text);button.addEventListener('click',()=>chooseAnswer(button,option,q));answers.append(button);
  });
  const feedback=document.querySelector('#feedback');feedback.textContent='';feedback.classList.remove('incorrect');
  const next=document.querySelector('#nextButton');next.disabled=true;next.innerHTML=current===round.length-1?'Ver resultado <span>→</span>':'Siguiente pregunta <span>→</span>';
}
function chooseAnswer(button,option,q){
  if(locked)return;locked=true;
  const buttons=[...document.querySelectorAll('.answer')];buttons.forEach(b=>b.disabled=true);
  const feedback=document.querySelector('#feedback');
  if(option===q.answer){
    correctAnswers++;streak++;bestStreak=Math.max(bestStreak,streak);const earned=100+Math.max(0,streak-1)*25;score+=earned;
    button.classList.add('correct');feedback.textContent=`¡Correcto! +${earned} puntos · ${q.explanation} (${q.reference})`;feedback.classList.remove('incorrect');playTone(true);
  }else{
    streak=0;button.classList.add('wrong');const right=buttons.find(b=>b.lastElementChild.textContent===q.answer);if(right)right.classList.add('correct');feedback.textContent=`La respuesta era ${q.answer}. ${q.explanation} (${q.reference})`;feedback.classList.add('incorrect');playTone(false);
  }
  document.querySelector('#liveScore').textContent=score;
  document.querySelector('#streakLabel').textContent=streak>1?`⚡ Racha de ${streak}`:'✧ Sigue aprendiendo';
  document.querySelector('#nextButton').disabled=false;
}
function nextQuestion(){if(!locked)return;current++;if(current>=round.length){finishGame();return;}renderQuestion();}
function finishGame(){
  document.querySelector('#progressFill').style.width='100%';
  const previous=getBestScore();if(score>previous)localStorage.setItem(bestScoreKey,String(score));refreshBestScore();
  document.querySelector('#finalScore').textContent=score;
  document.querySelector('#correctCount').textContent=`${correctAnswers} de ${round.length} correctas`;
  document.querySelector('#accuracyStat').textContent=`${Math.round(correctAnswers/round.length*100)}%`;
  document.querySelector('#bestStreak').textContent=bestStreak;
  const title=document.querySelector('#resultTitle'),message=document.querySelector('#resultMessage'),medal=document.querySelector('#resultMedal');
  if(correctAnswers===5){title.textContent='¡Excelente!';message.textContent='¡Lo tienes! Tu conocimiento bíblico está brillando.';medal.textContent='✦';}
  else if(correctAnswers>=3){title.textContent='¡Muy bien!';message.textContent='Vas por buen camino. Cada reto te enseña algo nuevo.';medal.textContent='✝';}
  else{title.textContent='¡Buen comienzo!';message.textContent='Sigue explorando estas historias. ¡Cada día puedes aprender más!';medal.textContent='♡';}
  if(score>previous&&score>0)toast('¡Nuevo récord personal!');
  showScreen('result');
}
function playTone(correct){if(!soundOn)return;try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.connect(gain);gain.connect(audioContext.destination);osc.frequency.value=correct?660:245;gain.gain.setValueAtTime(.08,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.22);osc.start();osc.stop(audioContext.currentTime+.22);}catch(e){}}
let toastTimer;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100);}

document.querySelectorAll('.category-card').forEach(button=>button.addEventListener('click',()=>{selectedCategory=button.dataset.category;document.querySelectorAll('.category-card').forEach(card=>card.classList.toggle('active',card===button));}));
document.querySelector('#startButton').addEventListener('click',startGame);
document.querySelector('#nextButton').addEventListener('click',nextQuestion);
document.querySelector('#quitButton').addEventListener('click',()=>{if(confirm('¿Quieres salir del reto? Se perderá el progreso de esta partida.'))showHome();});
document.querySelector('#playAgain').addEventListener('click',startGame);
document.querySelector('#homeButton').addEventListener('click',showHome);
document.querySelector('#soundToggle').addEventListener('click',event=>{soundOn=!soundOn;event.currentTarget.classList.toggle('sound-on',soundOn);event.currentTarget.setAttribute('aria-label',soundOn?'Desactivar sonido':'Activar sonido');event.currentTarget.title=soundOn?'Desactivar sonido':'Activar sonido';toast(soundOn?'Sonido activado':'Sonido desactivado');});
refreshBestScore();

